response:
**Gates before launch**

I run four gates in this order. First, grade.py must score an oracle label file built from answers.json at 100%. It must also fail an empty file and a file of wrong labels without crashing. The judge must pass a polite reference reply and fail a rude one. Second, I regrade round 3's saved trial outputs with today's grade.py as a control. The numbers must match the r03 rows in spe/prediction-log.md. If they differ, the grader changed. I then log a failure in spe/failures.md and stop. Third, I launch this script with `dryRun: true`. That runs 3 cells with 2 trials each under a $5 cap. I check that every trial output fits the schema, that the transcript scan finds every trial transcript, and that no trial touched a forbidden path. Fourth, I read the dry run's real spend and set `estTrialUSD`, `estJudgeUSD`, and `estOverheadUSD` from it. If 500 trials and 500 judge calls will not fit under $40, I halt and ask you, because cutting trials changes the approved plan. When all four gates pass, I commit the script as `SPE r04 evaluate (harness)` and launch the full run. The script repeats both selftests at launch as a hard stop. spe/predictions/r04.yaml stays exactly as committed.

**Script: spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-eval-round',
  description: 'SPE eval round. Configs B and C2 on 50 support tickets, 5 trials per cell. Code grader for labels, Opus judge for reply tone, 40 USD spend cap.',
  phases: [
    { title: 'Gate', detail: 'Check args and run the grader selftest' },
    { title: 'Setup', detail: 'Load configs, tickets, and rubric. Check counts. Run the judge selftest' },
    { title: 'Trials', detail: 'Base trials, ordered by trial index so a cap cuts both configs evenly' },
    { title: 'Grade', detail: 'Code checks, transcript peek scan, grade.py, then the tone judge' },
    { title: 'Extra trials', detail: 'More trials for split cells, inside the cap' },
    { title: 'Analysis', detail: 'Metrics and failure types' },
    { title: 'Critic', detail: 'Completeness check and results record' },
  ],
}

// SPE eval harness. The round number lives only in ROUND.
// This script never reads the saved prediction. The close-out compares results to it afterwards.
// Spend figures in this script are estimates from args. They are not measured.

const ROUND = 4
const RR = `r${String(ROUND).padStart(2, '0')}`
const PREV_RR = `r${String(ROUND - 1).padStart(2, '0')}`

// Fixed by the approved plan. Do not move these into args.
const PLAN = {
  configs: {
    B: { toolCount: 6, mustHave: [] },
    C2: { toolCount: 4, mustHave: ['check_status'] },
  },
  promptLines: 12,
  tickets: 50,
  trials: 5,
  capUSD: 40,
}

const DRY = args?.dryRun === true
const TRIALS_RUN = DRY ? 2 : PLAN.trials
const CAP = DRY ? 5 : PLAN.capUSD
const CONCURRENCY = Number(args?.concurrency ?? 8)
const EXTRA_PER_SPLIT_CELL = DRY ? 0 : 5
const VOID_HALT_FRACTION = 0.05
const RECORD_CHUNK = 100

const RUN_BASE = `spe/evals/runs/${RR}`
const PATHS = {
  grader: 'spe/evals/graders/grade.py',
  answers: 'spe/evals/tasks/answers.json',
  judge: 'spe/evals/graders/judge.md',
  prevHarness: `spe/evals/harness/${PREV_RR}-workflow.js`,
  failures: 'spe/failures.md',
  plan: `spe/plans/${RR}.md`,
  runDir: DRY ? `${RUN_BASE}/dry-run` : RUN_BASE,
}

// Trials must never touch these. Any hit voids the trial.
const FORBIDDEN = [
  'spe/evals/graders', 'grade.py', 'judge.md', 'answers.json',
  'spe/predictions', 'spe/plans', 'spe/prediction-log.md', 'spe/failures.md',
  'spe/spec', 'spe/evals/runs', 'spe/evals/harness',
]

function need(name, dryDefault) {
  const v = args?.[name]
  if (v !== undefined && v !== null && v !== '') return v
  if (DRY && dryDefault !== undefined) return dryDefault
  throw new Error(`Missing args.${name}. Set it from the dry run before the full launch.`)
}

const TRANSCRIPT_DIR = need('transcriptDir')
const EST = {
  trial: Number(need('estTrialUSD', 0.15)),
  judge: Number(need('estJudgeUSD', 0.08)),
  overhead: Number(need('estOverheadUSD', 1.5)),
}

// ---------- Ledger, halts, helpers ----------

const state = { committed: EST.overhead, skipped: [], all: [], warnings: [] }
const CTX = { trialModel: null, configs: null, tickets: null, rubric: null, allowed: {} }

function reserve(usd, what) {
  if (state.committed + usd > CAP) {
    state.skipped.push({ what, usd })
    log(`SKIP ${what}: estimated spend would reach $${(state.committed + usd).toFixed(2)}. Cap is $${CAP}.`)
    return false
  }
  state.committed += usd
  return true
}

class Halt extends Error {}
function halt(reason) {
  log(`HALT: ${reason}`)
  throw new Halt(reason)
}

const r3 = x => Math.round(x * 1000) / 1000
const r2 = x => Math.round(x * 100) / 100
const filled = s => typeof s === 'string' && s.trim().length > 0
const cellId = (config, ticket) => `${config}|${ticket}`
const isScored = t => t.status === 'ok' || t.status === 'malformed'

async function inBatches(thunks, size) {
  const out = []
  for (let i = 0; i < thunks.length; i += size) {
    const part = await parallel(thunks.slice(i, i + size))
    out.push(...part)
  }
  return out
}

function groupCells(list) {
  const m = new Map()
  for (const t of list) {
    const id = cellId(t.config, t.ticket)
    if (!m.has(id)) m.set(id, [])
    m.get(id).push(t)
  }
  return m
}

function rate(list, f) {
  return list.length ? r3(list.filter(f).length / list.length) : null
}

function prefixOf(cmd) {
  const cut = cmd.search(/[{<]/)
  return (cut === -1 ? cmd : cmd.slice(0, cut)).trim()
}

// ---------- Schemas ----------

const STR = { type: 'string' }
const STR_LIST = { type: 'array', items: STR }

const SELFTEST_SCHEMA = {
  type: 'object',
  required: ['command', 'oracle_fraction', 'empty_fraction', 'empty_crashed', 'wrong_fraction'],
  properties: {
    command: STR,
    oracle_fraction: { type: 'number' },
    empty_fraction: { type: 'number' },
    empty_crashed: { type: 'boolean' },
    wrong_fraction: { type: 'number' },
  },
}

const TOOL_DEF = {
  type: 'object',
  required: ['name', 'command', 'description'],
  properties: { name: STR, command: STR, description: STR },
}

const SETUP_SCHEMA = {
  type: 'object',
  required: ['trial_model', 'configs', 'tickets', 'answer_ids_match', 'missing_answer_ids', 'judge_rubric'],
  properties: {
    trial_model: STR,
    configs: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'system_prompt', 'tools'],
        properties: { id: STR, system_prompt: STR, tools: { type: 'array', items: TOOL_DEF } },
      },
    },
    tickets: {
      type: 'array',
      items: { type: 'object', required: ['id', 'text'], properties: { id: STR, text: STR } },
    },
    answer_ids_match: { type: 'boolean' },
    missing_answer_ids: STR_LIST,
    judge_rubric: STR,
  },
}

const TRIAL_SCHEMA = {
  type: 'object',
  required: ['label', 'reply', 'tool_calls'],
  properties: {
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: STR, priority: STR },
    },
    reply: STR,
    tool_calls: {
      type: 'array',
      items: { type: 'object', required: ['tool', 'command'], properties: { tool: STR, command: STR } },
    },
  },
}

const SCAN_SCHEMA = {
  type: 'object',
  required: ['labels_found', 'labels_missing', 'hits'],
  properties: {
    labels_found: { type: 'integer' },
    labels_missing: STR_LIST,
    hits: {
      type: 'array',
      items: { type: 'object', required: ['label', 'matched', 'line'], properties: { label: STR, matched: STR, line: STR } },
    },
  },
}

const GRADE_SCHEMA = {
  type: 'object',
  required: ['command', 'results'],
  properties: {
    command: STR,
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'category_correct', 'priority_correct'],
        properties: { key: STR, category_correct: { type: 'boolean' }, priority_correct: { type: 'boolean' } },
      },
    },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['score', 'pass', 'reason'],
  properties: { score: { type: 'number' }, pass: { type: 'boolean' }, reason: STR },
}

const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'grader_concerns'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'existing_id', 'what', 'how_to_spot', 'seen_in', 'fix'],
        properties: {
          name: STR, kind: STR, existing_id: STR, what: STR,
          how_to_spot: STR, seen_in: STR_LIST, fix: STR,
        },
      },
    },
    grader_concerns: STR_LIST,
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: STR_LIST },
}

const RECORD_SCHEMA = {
  type: 'object',
  required: ['path', 'lines_written'],
  properties: { path: STR, lines_written: { type: 'integer' } },
}

// ---------- Prompts ----------

function trialPrompt(cell) {
  const tools = cell.config.tools
    .map(t => `- ${t.name}: run \`${t.command}\`. ${t.description}`)
    .join('\n')
  return `You are the customer support agent under test. The system prompt below is your instructions.

<system_prompt>
${cell.config.system_prompt}
</system_prompt>

These are your only tools. Call a tool only by running its exact command with the arguments filled in.
${tools}

Rules:
- Do not open, read, list, or search any file or folder. Use only the tool commands above.
- Do not run any other command.
- Handle the ticket once. Then return the category and priority you chose, your reply to the customer, and every tool command you ran, copied exactly.

<ticket id="${cell.ticket.id}">
${cell.ticket.text}
</ticket>`
}

function judgePrompt(rubric, ticketText, reply) {
  return `You grade the tone of one customer support reply. Grade tone only. Do not grade whether the facts or labels are right. You do not know which system wrote the reply. Use only the rubric below. Do not open any files.

<rubric>
${rubric}
</rubric>

<ticket>
${ticketText}
</ticket>

<reply>
${reply}
</reply>

Return the score and the pass or fail that the rubric defines, and one sentence on why.`
}

function scanPrompt(labels) {
  return `You check whether any trial agent touched files it must not touch. Do not edit anything.
Agent transcripts for this workflow are under ${TRANSCRIPT_DIR}.
Find the transcript for each agent label in the list below. In each one, search every tool call and its input for these strings: ${FORBIDDEN.join(', ')}.
Report each hit with the label, the exact string from that list that matched, and the line where it appears.
Also report how many listed labels you found a transcript for, and list the labels you could not find.

Labels:
${labels.join('\n')}`
}

function gradePrompt(tag, recs) {
  const lines = recs
    .map(r => JSON.stringify({ key: r.key, ticket_id: r.ticket, category: r.out.label.category, priority: r.out.label.priority }))
    .join('\n')
  return `You run the round's code grader. Do not edit the grader or the answer key. Do not judge any label yourself.
1. Read ${PATHS.prevHarness} and run \`python3 ${PATHS.grader} --help\` to learn the grader's input format and flags.
2. Convert the JSON lines below into that input format, keeping each key. Write the file to ${PATHS.runDir}/labels-${tag}.
3. Run ${PATHS.grader} on that file against ${PATHS.answers}. Save the grader's raw output to ${PATHS.runDir}/grades-${tag}.json.
4. Return the exact command you ran, and one result per key exactly as the grader reported it.

${lines}`
}

// ---------- Trial and evaluation steps ----------

async function runTrial(cell, k, extra) {
  const key = `trial:${cell.config.id}:${cell.ticket.id}:t${k}`
  const rec = { key, config: cell.config.id, ticket: cell.ticket.id, k, extra, out: null, error: null }
  for (let attempt = 1; attempt <= 2; attempt++) {
    if (attempt === 2 && !reserve(EST.trial, `retry ${key}`)) break
    try {
      rec.out = await agent(trialPrompt(cell), {
        label: key,
        phase: extra ? 'Extra trials' : 'Trials',
        schema: TRIAL_SCHEMA,
        model: CTX.trialModel,
      })
      rec.error = null
      return rec
    } catch (e) {
      rec.error = String(e?.message ?? e)
      log(`Trial error ${key}, attempt ${attempt}: ${rec.error}`)
    }
  }
  return rec
}

function codeCheck(t) {
  if (t.error || !t.out) return { ...t, status: 'error' }
  const allowed = CTX.allowed[t.config]
  const cmds = (t.out.tool_calls || []).map(c => String(c.command || '').trim())
  const bad = cmds.filter(c => !allowed.some(p => c.startsWith(p)) || FORBIDDEN.some(f => c.includes(f)))
  if (bad.length) return { ...t, status: 'void', void_reason: `off-list command: ${bad[0].slice(0, 200)}` }
  const l = t.out.label || {}
  const wellFormed = filled(l.category) && filled(l.priority) && filled(t.out.reply)
  return { ...t, status: wellFormed ? 'ok' : 'malformed' }
}

async function evaluate(trials, tag) {
  const ph = tag === 'base' ? 'Grade' : 'Extra trials'
  phase(ph)

  // 1. Code checks come first.
  let recs = trials.map(codeCheck)

  // 2. Transcript scan for peeks.
  const withOutput = recs.filter(r => r.status !== 'error').map(r => r.key)
  if (withOutput.length) {
    const scan = await agent(scanPrompt(withOutput), { label: `scan:${tag}`, phase: ph, schema: SCAN_SCHEMA, model: 'opus' })
    if (scan.labels_found < withOutput.length) {
      halt(`Transcript scan found ${scan.labels_found} of ${withOutput.length} trial transcripts. Peeks cannot be ruled out. Missing: ${scan.labels_missing.slice(0, 10).join(', ')}`)
    }
    const hitBy = new Map(scan.hits.map(h => [h.label, h]))
    recs = recs.map(r => (hitBy.has(r.key) && r.status !== 'error'
      ? { ...r, status: 'void', void_reason: `transcript: ${hitBy.get(r.key).matched}` }
      : r))
    if (scan.hits.some(h => h.matched.includes('answers.json'))) {
      halt('A trial read the answer key. Trials can reach the key, so other trials may have seen it too.')
    }
  }
  const soFar = state.all.concat(recs)
  const voidCount = soFar.filter(r => r.status === 'void').length
  if (voidCount / Math.max(soFar.length, 1) > VOID_HALT_FRACTION) {
    halt(`${voidCount} of ${soFar.length} trials voided. That is above ${VOID_HALT_FRACTION * 100}%. Check trial isolation before trusting any number.`)
  }

  // 3. Code grader on well-formed trials.
  const toGrade = recs.filter(r => r.status === 'ok')
  if (toGrade.length) {
    const g = await agent(gradePrompt(tag, toGrade), { label: `grade:${tag}`, phase: ph, schema: GRADE_SCHEMA, model: 'opus' })
    const byKey = new Map(g.results.map(x => [x.key, x]))
    const missing = toGrade.filter(r => !byKey.has(r.key))
    if (missing.length || g.results.length !== toGrade.length) {
      halt(`Grader returned ${g.results.length} results for ${toGrade.length} trials. Treat the grader as broken.`)
    }
    recs = recs.map(r => (byKey.has(r.key) ? { ...r, grade: byKey.get(r.key) } : r))
  }

  // 4. Judge only what code cannot check: reply tone. Blind to config.
  const textOf = new Map(CTX.tickets.map(t => [t.id, t.text]))
  let n = 0
  const judgeThunks = recs.filter(r => r.status === 'ok').map(r => {
    n += 1
    const blind = `${tag}-${n}`
    return async () => {
      try {
        const j = await agent(judgePrompt(CTX.rubric, textOf.get(r.ticket), r.out.reply), {
          label: `judge:${blind}`, phase: ph, schema: JUDGE_SCHEMA, model: 'opus',
        })
        return [r.key, j]
      } catch (e) {
        return [r.key, null]
      }
    }
  })
  const judged = new Map(await inBatches(judgeThunks, CONCURRENCY))

  // Release judge reservations for trials that skipped the judge.
  const unjudged = recs.filter(r => r.status !== 'ok').length
  state.committed -= unjudged * EST.judge

  // 5. Pass means both labels right and tone pass.
  recs = recs.map(r => {
    if (r.status !== 'ok') return { ...r, pass: false }
    const j = judged.get(r.key)
    if (!j) return { ...r, status: 'judge_error', judge: null, pass: false }
    const pass = r.grade.category_correct === true && r.grade.priority_correct === true && j.pass === true
    return { ...r, judge: j, pass }
  })
  return recs
}

function configMetrics(all, cfg, baseOnly) {
  const mine = all.filter(t => t.config === cfg && (!baseOnly || !t.extra))
  const scored = mine.filter(isScored)
  const cells = [...groupCells(scored).values()]
  return {
    trials_scored: scored.length,
    voided: mine.filter(t => t.status === 'void').length,
    errors: mine.filter(t => t.status === 'error').length,
    judge_errors: mine.filter(t => t.status === 'judge_error').length,
    malformed: mine.filter(t => t.status === 'malformed').length,
    category_accuracy: rate(scored, t => t.grade?.category_correct === true),
    priority_accuracy: rate(scored, t => t.grade?.priority_correct === true),
    labels_correct: rate(scored, t => t.grade?.category_correct === true && t.grade?.priority_correct === true),
    tone_pass: rate(scored, t => t.judge?.pass === true),
    all_pass: rate(scored, t => t.pass),
    mean_tool_calls: scored.length
      ? r3(scored.reduce((s, t) => s + (t.out?.tool_calls?.length || 0), 0) / scored.length)
      : null,
    check_status_used: rate(scored, t => (t.out?.tool_calls || []).some(c => c.tool === 'check_status')),
    cells_all_pass: cells.filter(c => c.every(t => t.pass)).length,
    cells_split: cells.filter(c => c.some(t => t.pass) && !c.every(t => t.pass)).length,
    cells_all_fail: cells.filter(c => !c.some(t => t.pass)).length,
  }
}

// ---------- Main ----------

async function main() {
  // Gate
  phase('Gate')
  log(`Round ${ROUND}${DRY ? ' DRY RUN' : ''}. Cap $${CAP}. Estimates per trial $${EST.trial}, per judge $${EST.judge}, overhead $${EST.overhead}.`)
  const st = await agent(
    `You check the round's code grader before any trial runs. Do not edit the grader or the answer key.
Grader: ${PATHS.grader}. Answer key: ${PATHS.answers}. Use the input format that ${PATHS.prevHarness} used.
Write three label files under ${PATHS.runDir}/selftest/:
1. oracle: every ticket labeled with its correct category and priority from the answer key.
2. empty: a file with no labels.
3. wrong: every ticket labeled with a category and a priority that both differ from the answer key.
Run the grader on each file. Report the command you used, the fraction of tickets it marks fully correct for each file, and whether it crashed on the empty file.`,
    { label: 'gate:grader-selftest', phase: 'Gate', schema: SELFTEST_SCHEMA, model: 'opus' },
  )
  if (st.oracle_fraction !== 1 || st.empty_crashed || st.empty_fraction !== 0 || st.wrong_fraction !== 0) {
    halt(`Grader selftest failed: oracle ${st.oracle_fraction}, empty ${st.empty_fraction} (crashed ${st.empty_crashed}), wrong ${st.wrong_fraction}.`)
  }

  // Setup
  phase('Setup')
  const setup = await agent(
    `Load the inputs for this eval round. Do not edit any file. Never return any answer label.
1. Read ${PATHS.prevHarness}. It shows where the tickets live, where each config's system prompt and tool definitions live, how tools are called, and which model ran the trials. Use the same locations and the same trial model.
2. For configs B and C2, return the system prompt text verbatim. Return each tool with its name, the exact command that calls it, and its description. Return what the files say even if it looks wrong. Do not fix anything.
3. Return every ticket with its id and full text, verbatim.
4. Open ${PATHS.answers}. Check that it has an entry for every ticket id and no others. Return true or false and any missing ids.
5. Return the full text of ${PATHS.judge} verbatim.`,
    { label: 'setup:load', phase: 'Setup', schema: SETUP_SCHEMA, model: 'opus' },
  )

  const ids = setup.tickets.map(t => t.id)
  if (setup.tickets.length !== PLAN.tickets) halt(`Expected ${PLAN.tickets} tickets, found ${setup.tickets.length}.`)
  if (new Set(ids).size !== ids.length) halt('Ticket ids are not unique.')
  if (!setup.answer_ids_match) halt(`Answer key does not match the tickets. Missing: ${setup.missing_answer_ids.join(', ')}`)
  if (!filled(setup.judge_rubric)) halt('Judge rubric is empty.')
  if (!filled(setup.trial_model)) halt('Trial model not found in the previous harness.')

  const configs = []
  for (const [id, spec] of Object.entries(PLAN.configs)) {
    const c = setup.configs.find(x => x.id === id)
    if (!c) halt(`Config ${id} not found.`)
    if (c.tools.length !== spec.toolCount) halt(`Config ${id} has ${c.tools.length} tools. The plan says ${spec.toolCount}.`)
    for (const name of spec.mustHave) {
      if (!c.tools.some(t => t.name === name)) halt(`Config ${id} is missing the ${name} tool.`)
    }
    const lines = c.system_prompt.trim().split('\n').length
    if (lines !== PLAN.promptLines) {
      state.warnings.push(`Config ${id} prompt has ${lines} lines. The plan says ${PLAN.promptLines}.`)
      log(`WARNING: config ${id} prompt has ${lines} lines, plan says ${PLAN.promptLines}.`)
    }
    CTX.allowed[id] = c.tools.map(t => prefixOf(t.command)).filter(filled)
    configs.push(c)
  }
  CTX.configs = configs
  CTX.tickets = setup.tickets
  CTX.rubric = setup.judge_rubric
  CTX.trialModel = setup.trial_model

  // Judge selftest with fixed replies.
  const probeTicket = 'Our nightly export failed again last night. Can you look into it?'
  const POLITE = 'Hi Sam, thanks for flagging this, and I am sorry the export failed again. I have restarted the job and it should finish within the hour. I will check it at 3pm and update you here.'
  const RUDE = 'Read the docs. This is not a bug. Stop opening tickets about it.'
  const probes = await parallel([
    () => agent(judgePrompt(CTX.rubric, probeTicket, POLITE), { label: 'gate:judge-polite', phase: 'Setup', schema: JUDGE_SCHEMA, model: 'opus' }),
    () => agent(judgePrompt(CTX.rubric, probeTicket, RUDE), { label: 'gate:judge-rude', phase: 'Setup', schema: JUDGE_SCHEMA, model: 'opus' }),
  ])
  if (probes[0].pass !== true || probes[1].pass !== false) {
    halt(`Judge selftest failed: polite pass=${probes[0].pass}, rude pass=${probes[1].pass}.`)
  }

  // Trials
  phase('Trials')
  const tickets = DRY ? setup.tickets.slice(0, 2) : setup.tickets
  let cells = []
  for (const ticket of tickets) {
    for (const config of configs) cells.push({ ticket, config })
  }
  if (DRY) cells = cells.slice(0, 3)
  const cellById = new Map(cells.map(c => [cellId(c.config.id, c.ticket.id), c]))

  const thunks = []
  for (let k = 1; k <= TRIALS_RUN; k++) {
    for (const cell of cells) {
      if (!reserve(EST.trial + EST.judge, `trial ${cell.config.id}:${cell.ticket.id}:t${k}`)) continue
      thunks.push(() => runTrial(cell, k, false))
    }
  }
  log(`Base trials planned: ${thunks.length} of ${cells.length * TRIALS_RUN}. Skipped by cap: ${state.skipped.length}. Estimated committed spend: $${state.committed.toFixed(2)}.`)
  const baseRaw = await inBatches(thunks, CONCURRENCY)

  // Grade base trials
  const base = await evaluate(baseRaw, 'base')
  state.all.push(...base)

  // Extra trials for split cells
  phase('Extra trials')
  const baseCells = groupCells(base.filter(isScored))
  const split = [...baseCells.entries()]
    .filter(([, ts]) => ts.some(t => t.pass) && !ts.every(t => t.pass))
    .map(([id]) => id)
  log(`Split cells: ${split.length}.`)
  const extraThunks = []
  for (let i = 1; i <= EXTRA_PER_SPLIT_CELL; i++) {
    for (const id of split) {
      const cell = cellById.get(id)
      const k = TRIALS_RUN + i
      if (!reserve(EST.trial + EST.judge, `extra ${cell.config.id}:${cell.ticket.id}:t${k}`)) continue
      extraThunks.push(() => runTrial(cell, k, true))
    }
  }
  if (extraThunks.length) {
    const extraRaw = await inBatches(extraThunks, CONCURRENCY)
    const extras = await evaluate(extraRaw, 'extra')
    state.all.push(...extras)
  }

  // Analysis
  phase('Analysis')
  const all = state.all
  const metricsBase = {}
  const metricsWithExtras = {}
  for (const id of Object.keys(PLAN.configs)) {
    metricsBase[id] = configMetrics(all, id, true)
    metricsWithExtras[id] = configMetrics(all, id, false)
  }
  const cellTable = cells.map(c => {
    const ts = all.filter(t => t.config === c.config.id && t.ticket === c.ticket.id && isScored(t))
    const b = ts.filter(t => !t.extra)
    const x = ts.filter(t => t.extra)
    return {
      config: c.config.id, ticket: c.ticket.id,
      base_pass: b.filter(t => t.pass).length, base_n: b.length,
      extra_pass: x.filter(t => t.pass).length, extra_n: x.length,
    }
  })

  // Completeness by code
  const gaps = []
  for (const c of cells) {
    const have = all.filter(t => !t.extra && t.config === c.config.id && t.ticket === c.ticket.id).length
    const skippedHere = state.skipped.filter(s => s.what.startsWith(`trial ${c.config.id}:${c.ticket.id}:`)).length
    if (have + skippedHere !== TRIALS_RUN) {
      gaps.push(`${cellId(c.config.id, c.ticket.id)}: ${have} run, ${skippedHere} skipped, ${TRIALS_RUN} planned`)
    }
  }

  const failing = all
    .filter(t => isScored(t) && !t.pass)
    .slice(0, 300)
    .map(t => ({
      key: t.key, config: t.config, ticket: t.ticket, status: t.status,
      label: t.out?.label ?? null,
      category_correct: t.grade?.category_correct ?? null,
      priority_correct: t.grade?.priority_correct ?? null,
      tone_pass: t.judge?.pass ?? null, tone_reason: t.judge?.reason ?? null,
      tools: (t.out?.tool_calls || []).map(c => c.tool),
    }))

  const analysis = await agent(
    `You analyse the failures from this eval round. Do not edit any file. Do not open anything under spe/predictions.
Read ${PATHS.failures} first. Reuse an existing F id when a failure matches a known type. Use "new" as existing_id otherwise.
You may read ${PATHS.answers} and the files in ${PATHS.runDir} to see the expected labels.
For each failure type, give the name, the kind (label, tone, tool use, format, isolation, or grader), what happens, how to spot it, the trial keys it was seen in, and a proposed fix.
If any failure looks like a grader or judge mistake instead of an agent mistake, list it under grader_concerns.

Metrics, first ${TRIALS_RUN} trials per cell:
${JSON.stringify(metricsBase)}

Failing trials:
${JSON.stringify(failing)}`,
    { label: 'analysis:failures', phase: 'Analysis', schema: ANALYSIS_SCHEMA, model: 'opus' },
  )

  // Critic
  phase('Critic')
  const critic = await agent(
    `You check this eval round for completeness. Do not edit any file. Do not compare results to predictions. The close-out does that.
Read ${PATHS.plan} to see which metrics and configs the plan measures. Check that every planned metric has a measured value for every config below, that the trial counts add up, and that the failure analysis covers every config that failed.
Report each gap as one plain sentence.

Code-found gaps: ${JSON.stringify(gaps)}
Skipped by cap: ${state.skipped.length}
Metrics, first ${TRIALS_RUN} trials per cell: ${JSON.stringify(metricsBase)}
Metrics with extras: ${JSON.stringify(metricsWithExtras)}
Failure types: ${JSON.stringify(analysis.failure_types.map(f => ({ name: f.name, seen_in: f.seen_in.length })))}`,
    { label: 'critic:completeness', phase: 'Critic', schema: CRITIC_SCHEMA, model: 'opus' },
  )

  // Record trial records to disk in chunks.
  const records = all.map(t => ({
    key: t.key, config: t.config, ticket: t.ticket, k: t.k, extra: t.extra,
    status: t.status, void_reason: t.void_reason ?? null, error: t.error ?? null,
    label: t.out?.label ?? null, reply: t.out?.reply ?? null, tool_calls: t.out?.tool_calls ?? [],
    grade: t.grade ?? null, judge: t.judge ?? null, pass: t.pass === true,
  }))
  const recordThunks = []
  for (let i = 0; i < records.length; i += RECORD_CHUNK) {
    const part = records.slice(i, i + RECORD_CHUNK)
    const name = `trials-${String(i / RECORD_CHUNK + 1).padStart(2, '0')}.jsonl`
    recordThunks.push(() => agent(
      `Write the JSON lines below to ${PATHS.runDir}/${name}, exactly as given, one object per line. Do not change or add anything. Return the path and the number of lines written.

${part.map(r => JSON.stringify(r)).join('\n')}`,
      { label: `record:${name}`, phase: 'Critic', schema: RECORD_SCHEMA, model: 'opus' },
    ))
  }
  const written = await parallel(recordThunks)
  const linesWritten = written.reduce((s, w) => s + w.lines_written, 0)
  if (linesWritten !== records.length) gaps.push(`Recorded ${linesWritten} of ${records.length} trial records.`)

  return {
    round: ROUND,
    dry_run: DRY,
    halted: false,
    spend_estimate_usd: r2(state.committed),
    cap_usd: CAP,
    spend_note: 'Estimated from args. Read real spend from usage before writing the close-out.',
    grader_selftest: st,
    metrics_base: metricsBase,
    metrics_with_extras: metricsWithExtras,
    split_cells: split,
    cells: cellTable,
    skipped: state.skipped,
    voided: all.filter(t => t.status === 'void').map(t => ({ key: t.key, reason: t.void_reason })),
    errors: all.filter(t => t.status === 'error' || t.status === 'judge_error').map(t => ({ key: t.key, status: t.status, error: t.error ?? null })),
    completeness_gaps: gaps,
    critic,
    failure_types: analysis.failure_types,
    grader_concerns: analysis.grader_concerns,
    config_warnings: state.warnings,
    record_files: written.map(w => w.path),
  }
}

try {
  return await main()
} catch (e) {
  if (e instanceof Halt) {
    return {
      round: ROUND,
      dry_run: DRY,
      halted: true,
      reason: e.message,
      spend_estimate_usd: r2(state.committed),
      trials_done: state.all.length,
      skipped: state.skipped,
    }
  }
  throw e
}
